/** Tiny Observable with the RxJS constructor/subscribe shape. */
class MiniObservable<T> implements ObservableLike<T> {
  constructor(private readonly producer: (subscriber: SubscriberLike<T>) => unknown) {}
  subscribe(observer: Partial<SubscriberLike<T>>): { unsubscribe(): void } {
    const teardown = this.producer({
      next: (v) => {
        observer.next?.(v);
      },
      error: (e) => {
        observer.error?.(e);
      },
      complete: () => {
        observer.complete?.();
      },
    });
    return {
      unsubscribe: () => {
        if (typeof teardown === "function") (teardown as () => void)();
      },
    };
  }
}

